import json

# Read the jsonl file and analyze the overall structure
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_11/projects/phase-gated-compound-sparse/logs/chats/worker_analysis_rebootstrap_importance_b10000_20260514T090502.jsonl', 'r') as f:
    lines = f.readlines()

print("First few lines content types:")
for i in range(min(5, len(lines))):
    obj = json.loads(lines[i])
    print(f"\nLine {i} type: {obj.get('type')}")
    if 'message' in obj:
        msg = obj['message']
        if isinstance(msg, dict):
            print(f"  Message role: {msg.get('role')}")
            content = msg.get('content', [])
            if isinstance(content, list):
                print(f"  Content items: {len(content)}")
                for j, item in enumerate(content):
                    if isinstance(item, dict):
                        print(f"    Item {j} type: {item.get('type')}")
                        if item.get('type') == 'text':
                            text = item.get('text', '')
                            print(f"      Text length: {len(text)}")
                        elif item.get('type') == 'tool_use':
                            print(f"      Tool: {item.get('name')}")

# Find lines with tool results that might contain data
print("\n\nLooking for tool results with data...")
for i, line in enumerate(lines):
    obj = json.loads(line)
    if obj.get('type') == 'user':
        content = obj.get('message', {}).get('content', [])
        if isinstance(content, list):
            for item in content:
                if isinstance(item, dict) and item.get('type') == 'tool_result':
                    result_content = item.get('content', '')
                    if isinstance(result_content, str) and any(x in result_content for x in ['ds_imp_s', 'qw_imp_s', 'cohens_d']):
                        print(f"Line {i}: Found tool result with experiment data")
                        # Try to parse it
                        try:
                            result_data = json.loads(result_content)
                            print(f"  Parsed successfully, keys: {list(result_data.keys())[:5]}")
                        except:
                            print(f"  Content preview: {result_content[:500]}")
